package com.saas.logging.actuator;

import com.saas.logging.service.TenantLoggingService;
import org.springframework.boot.actuate.endpoint.annotation.Selector;
import org.springframework.boot.actuate.endpoint.annotation.WriteOperation;
import org.springframework.boot.actuate.endpoint.web.annotation.WebEndpoint;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Component;

@Component
@WebEndpoint(id = "tenant-log-levels")
public class TenantLoggingActuatorEndpoint {

    private final TenantLoggingService loggingService;

    public TenantLoggingActuatorEndpoint(TenantLoggingService loggingService) {
        this.loggingService = loggingService;
    }

    @WriteOperation
    public String setLogLevel(@Selector String tenantCode, String loggerName, String level) {
        Authentication auth = SecurityContextHolder.getContext().getAuthentication();
        if (auth == null || !auth.getName().equalsIgnoreCase(tenantCode)) {
            throw new AccessDeniedException("Caller is not authorized to alter log thresholds for " + tenantCode);
        }
        loggingService.configureLogLevel(tenantCode, loggerName, level);
        return "Log level set to " + level + " for tenant " + tenantCode;
    }
}
